package com.resume.account.data

import jakarta.persistence.Column
import jakarta.persistence.Entity
import jakarta.persistence.Id
import jakarta.persistence.Table
import org.hibernate.annotations.JdbcTypeCode
import org.hibernate.type.SqlTypes
import java.time.Instant

/**
 * Feature 05 schema (Flyway V3__concierge.sql; TL 02 + additive extensions
 * documented in the migration). TEXT ids generated by the domain; JSONB
 * columns map to typed values. No JPA relationships: RLS keeps every access
 * path predicate-scoped.
 */
data class SowEntry(val kind: String = "", val volume: Int? = null)

/** Exit handoff inventory (BA 03 step 2; BR-10): each item timestamped on commit. */
data class HandoffState(
    val startedAt: Instant? = null,
    val scheduledWork: String? = null,
    val items: List<HandoffItem> = emptyList(),
    val completedAt: Instant? = null,
)

data class HandoffItem(val key: String = "", val at: Instant? = null)

@Entity
@Table(name = "concierge_sow_templates")
class ConciergeTemplateEntity(
    @Id var id: String = "",
    var name: String = "",
    @JdbcTypeCode(SqlTypes.JSON) var menu: MutableList<String> = mutableListOf(),
    var version: Int = 1,
    var active: Boolean = true,
    @Column(name = "created_at") var createdAt: Instant = Instant.now(),
)

@Entity
@Table(name = "concierge_staff")
class ConciergeStaffEntity(
    @Id var id: String = "",
    @Column(name = "user_id") var userId: String = "",
    /** operator | owner (CHECK constraint enforces the set). */
    var role: String = "operator",
    /** Display name shown to the client (BA 04 "names visible to the client"). */
    var name: String? = null,
    var active: Boolean = true,
    @Column(name = "created_at") var createdAt: Instant = Instant.now(),
    @Column(name = "removed_at") var removedAt: Instant? = null,
)

@Entity
@Table(name = "concierge_contracts")
class ConciergeContractEntity(
    @Id var id: String = "",
    @Column(name = "user_id") var userId: String = "",
    /** draft | active | paused | exited. */
    var status: String = "draft",
    @Column(name = "sla_tier") var slaTier: String = "",
    @JdbcTypeCode(SqlTypes.JSON) var sow: MutableList<SowEntry> = mutableListOf(),
    @Column(name = "sow_version") var sowVersion: Int = 1,
    /** pause | exit while a transition awaits its counterpart (BR-10). */
    @Column(name = "pending_transition") var pendingTransition: String? = null,
    /** client | agency - who must be confirmed by the counterpart (BR-10). */
    @Column(name = "pending_by") var pendingBy: String? = null,
    @JdbcTypeCode(SqlTypes.JSON) var handoff: HandoffState? = null,
    @Column(name = "created_at") var createdAt: Instant = Instant.now(),
    @Column(name = "activated_at") var activatedAt: Instant? = null,
    @Column(name = "paused_at") var pausedAt: Instant? = null,
    @Column(name = "exited_at") var exitedAt: Instant? = null,
    @Column(name = "updated_at") var updatedAt: Instant = Instant.now(),
)

@Entity
@Table(name = "concierge_tasks")
class ConciergeTaskEntity(
    @Id var id: String = "",
    @Column(name = "contract_id") var contractId: String = "",
    @Column(name = "user_id") var userId: String = "",
    var kind: String = "",
    /** requested | approved | in_progress | done | refused | cancelled. */
    var status: String = "requested",
    /** client | scheduled. */
    var origin: String = "client",
    var notes: String? = null,
    @Column(name = "operator_id") var operatorId: String? = null,
    @JdbcTypeCode(SqlTypes.JSON) var workRefs: MutableList<String> = mutableListOf(),
    @Column(name = "refusal_reason") var refusalReason: String? = null,
    var referral: String? = null,
    /** Durable miss records (BR-06): a recorded miss is never silently cleared. */
    @Column(name = "missed_response_at") var missedResponseAt: Instant? = null,
    @Column(name = "missed_completion_at") var missedCompletionAt: Instant? = null,
    @Column(name = "requested_at") var requestedAt: Instant = Instant.now(),
    @Column(name = "approved_at") var approvedAt: Instant? = null,
    @Column(name = "started_at") var startedAt: Instant? = null,
    @Column(name = "completed_at") var completedAt: Instant? = null,
    @Column(name = "updated_at") var updatedAt: Instant = Instant.now(),
)

/**
 * Append-only approval ledger (BA 05: "never edited, only superseded by a new
 * record"). The app role holds INSERT/SELECT only; the DB revokes UPDATE/DELETE.
 * `taskId` is null for the setup-plan approval (BA 03 step 2).
 */
@Entity
@Table(name = "concierge_approvals")
class ConciergeApprovalEntity(
    @Id var id: String = "",
    @Column(name = "contract_id") var contractId: String = "",
    @Column(name = "task_id") var taskId: String? = null,
    @Column(name = "user_id") var userId: String = "",
    var scope: String = "",
    /** dashboard | signed_email. */
    var channel: String = "dashboard",
    @Column(name = "approved_by") var approvedBy: String = "",
    @Column(name = "approved_at") var approvedAt: Instant = Instant.now(),
    var jti: String? = null,
)
